<title>SNAKE · terminal garden</title>
<style>
  :root{
    --bg:#070d0a;
    --panel:#0d1712;
    --panel2:#0a120e;
    --line:#1d3327;
    --line2:#2c4d3a;
    --lime:#b6f04a;
    --mint:#7fe370;
    --teal:#39d2a8;
    --amber:#ffb454;
    --coral:#ff5d4d;
    --ink:#e9f6ec;
    --dim:#7fa392;
    --faint:#486656;
    --mono:ui-monospace,"Cascadia Mono","SF Mono",Menlo,Consolas,"Liberation Mono",monospace;
    --sans:system-ui,-apple-system,"Segoe UI",sans-serif;
  }
  *{box-sizing:border-box}
  html,body{margin:0;padding:0}
  body{
    min-height:100vh;
    display:grid;
    place-items:center;
    padding:28px 12px;
    background:
      radial-gradient(900px 600px at 12% -8%, rgba(57,210,168,.10), transparent 60%),
      radial-gradient(1000px 700px at 95% 108%, rgba(126,227,112,.08), transparent 60%),
      var(--bg);
    color:var(--ink);
    font-family:var(--sans);
    overflow-x:auto;
  }
  /* drifting ambient glow */
  body::before{
    content:"";position:fixed;inset:-30%;pointer-events:none;z-index:0;
    background:
      radial-gradient(420px 340px at 30% 40%, rgba(182,240,74,.06), transparent 70%),
      radial-gradient(520px 420px at 70% 60%, rgba(57,210,168,.05), transparent 70%);
    animation:drift 22s ease-in-out infinite alternate;
  }
  /* faint blueprint grid over the whole page */
  body::after{
    content:"";position:fixed;inset:0;pointer-events:none;z-index:0;
    background:
      repeating-linear-gradient(0deg, rgba(140,220,180,.035) 0 1px, transparent 1px 26px),
      repeating-linear-gradient(90deg, rgba(140,220,180,.035) 0 1px, transparent 1px 26px);
    mask-image:radial-gradient(80% 80% at 50% 45%, #000 40%, transparent 100%);
    -webkit-mask-image:radial-gradient(80% 80% at 50% 45%, #000 40%, transparent 100%);
  }
  @keyframes drift{
    from{transform:translate(-3%,-2%) scale(1)}
    to{transform:translate(3%,3%) scale(1.06)}
  }

  .cab{position:relative;z-index:1;display:flex;flex-direction:column;gap:14px;width:max-content;max-width:calc(100vw - 20px)}

  /* ── masthead ─────────────────────────────── */
  .masthead{display:flex;align-items:flex-end;justify-content:space-between;gap:16px}
  .logo{display:flex;align-items:center;gap:14px}
  .worm{display:flex;gap:3px;transform:translateY(1px)}
  .worm i{
    width:9px;height:9px;border-radius:3px;display:block;
    animation:slither 1.5s ease-in-out infinite;
  }
  .worm i:nth-child(1){background:var(--lime);animation-delay:0s}
  .worm i:nth-child(2){background:#9de95c;animation-delay:.12s}
  .worm i:nth-child(3){background:#6fdd6d;animation-delay:.24s}
  .worm i:nth-child(4){background:#47d489;animation-delay:.36s}
  .worm i:nth-child(5){background:var(--teal);animation-delay:.48s}
  @keyframes slither{
    0%,100%{transform:translateY(0)}
    30%{transform:translateY(-4px)}
    60%{transform:translateY(1px)}
  }
  h1{
    margin:0;font-family:var(--mono);font-weight:700;font-size:30px;line-height:1;
    letter-spacing:.38em;color:var(--lime);
    text-shadow:0 0 22px rgba(182,240,74,.35), 0 0 2px rgba(182,240,74,.6);
