  .chip::before{
    content:"";position:absolute;left:10px;top:50%;width:7px;height:7px;border-radius:50%;
    transform:translateY(-50%);background:var(--amber);box-shadow:0 0 8px currentColor;
    animation:blip 1.6s ease-in-out infinite;
  }
  @keyframes blip{0%,100%{opacity:1}50%{opacity:.35}}
  .chip.ready{color:var(--amber)} .chip.ready::before{background:var(--amber)}
  .chip.running{color:var(--lime)} .chip.running::before{background:var(--lime)}
  .chip.paused{color:var(--amber)} .chip.paused::before{background:var(--amber)}
  .chip.over{color:var(--coral)} .chip.over::before{background:var(--coral);animation:none}
  #snd{
    font-family:var(--mono);font-size:10px;letter-spacing:.18em;color:var(--dim);
    background:var(--panel2);border:1px solid var(--line);border-radius:999px;
    padding:6px 12px;cursor:pointer;transition:border-color .2s,color .2s,transform .12s;
  }
  #snd:hover{border-color:var(--line2);color:var(--ink);transform:translateY(-1px)}

  /* ── HUD ──────────────────────────────────── */
  .hud{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:10px}
  .stat{
    background:linear-gradient(180deg,var(--panel),var(--panel2));
    border:1px solid var(--line);border-radius:10px;padding:9px 14px 11px;
    display:flex;flex-direction:column;gap:2px;min-width:96px;
    box-shadow:inset 0 1px 0 rgba(255,255,255,.03);
  }
  .stat .label{font-size:10px;letter-spacing:.24em;color:var(--faint);font-weight:600}
  .stat .value{font-family:var(--mono);font-weight:700;font-size:22px;color:var(--ink);line-height:1.1}
  .stat.primary{border-color:rgba(182,240,74,.35)}
  .stat.primary .value{font-size:28px;color:var(--lime);text-shadow:0 0 14px rgba(182,240,74,.3)}
  .value.pop{animation:pop .32s ease-out}
  @keyframes pop{
    0%{transform:scale(1)} 35%{transform:scale(1.28)} 100%{transform:scale(1)}
  }

  /* ── board ────────────────────────────────── */
  .frame{
    position:relative;align-self:center;padding:10px;border-radius:14px;
    background:linear-gradient(180deg,#0f1c15,#0a130e);
    border:1px solid var(--line2);
    box-shadow:
      0 0 0 1px rgba(0,0,0,.7),
      0 26px 70px -24px rgba(0,0,0,.9),
      0 0 46px -14px rgba(57,210,168,.28),
      inset 0 0 26px rgba(0,0,0,.55);
  }
  .frame::before,.frame::after{content:"";position:absolute;width:24px;height:24px;pointer-events:none}
  .frame::before{top:-1px;left:-1px;border-top:2px solid var(--lime);border-left:2px solid var(--lime);border-radius:14px 0 0 0;opacity:.85}
  .frame::after{bottom:-1px;right:-1px;border-bottom:2px solid var(--teal);border-right:2px solid var(--teal);border-radius:0 0 14px 0;opacity:.85}
  .frame.eat{animation:framePulse .45s ease-out}
  @keyframes framePulse{
    0%{box-shadow:0 0 0 1px rgba(0,0,0,.7),0 26px 70px -24px rgba(0,0,0,.9),0 0 70px -8px rgba(182,240,74,.65),inset 0 0 26px rgba(0,0,0,.55)}
    100%{box-shadow:0 0 0 1px rgba(0,0,0,.7),0 26px 70px -24px rgba(0,0,0,.9),0 0 46px -14px rgba(57,210,168,.28),inset 0 0 26px rgba(0,0,0,.55)}
  }
  #snake{
    display:block;width:480px;height:480px;border-radius:8px;
    background:#0a130f;
  }
  .scan{
    position:absolute;inset:10px;border-radius:8px;pointer-events:none;
    background:repeating-linear-gradient(0deg, rgba(255,255,255,.026) 0 1px, transparent 1px 3px);
  }
  .banner{
    position:absolute;left:22px;right:22px;top:22px;z-index:3;pointer-events:none;
    text-align:center;font-family:var(--mono);font-size:12px;letter-spacing:.24em;
    padding:11px 14px;border-radius:8px;color:var(--dim);
    background:rgba(6,11,9,.9);border:1px solid var(--line2);
    transition:opacity .25s ease,transform .25s ease;
  }
  .banner.hidden{opacity:0;transform:translateY(-8px)}
  .banner.ready{color:var(--lime);border-color:rgba(182,240,74,.4)}
  .banner.paused{color:var(--amber);border-color:rgba(255,180,84,.4)}
  .banner.over{color:var(--coral);border-color:rgba(255,93,77,.45)}
  .banner.win{color:var(--teal);border-color:rgba(57,210,168,.5)}

  /* ── controls ─────────────────────────────── */
  .controls{display:flex;gap:12px}
  .controls button{
    flex:1;font-family:var(--mono);font-size:13px;font-weight:700;letter-spacing:.2em;
    color:var(--ink);background:linear-gradient(180deg,#101d15,#0b1510);
    border:1px solid var(--line2);border-radius:9px;padding:13px 10px;cursor:pointer;
    box-shadow:0 3px 0 rgba(2,8,5,.9), inset 0 1px 0 rgba(255,255,255,.05);
    transition:transform .12s ease, box-shadow .2s ease, border-color .2s ease, opacity .2s;
    --acc:var(--lime);
  }
  #pause{--acc:var(--amber)} #reset{--acc:var(--coral)}
  .controls button:hover{
    transform:translateY(-2px);border-color:var(--acc);
    box-shadow:0 5px 0 rgba(2,8,5,.9), 0 0 22px -6px var(--acc), inset 0 1px 0 rgba(255,255,255,.06);
  }
  .controls button:active{transform:translateY(1px);box-shadow:0 1px 0 rgba(2,8,5,.9)}
  .controls button:focus-visible{outline:2px solid var(--acc);outline-offset:3px}
  .controls button:disabled{opacity:.4;cursor:default;transform:none;box-shadow:0 3px 0 rgba(2,8,5,.9)}
  .controls button.dim{opacity:.55}

  /* ── footer keys ──────────────────────────── */
  .keys{display:flex;justify-content:center;gap:22px;flex-wrap:wrap;font-size:11px;color:var(--faint);letter-spacing:.06em}
  .keys span{display:flex;align-items:center;gap:6px}
  kbd{
    font-family:var(--mono);font-size:10px;color:var(--dim);
    background:#0c1611;border:1px solid var(--line);border-bottom-width:2px;
    border-radius:5px;padding:3px 7px;min-width:14px;text-align:center;display:inline-block;
  }

  @media (prefers-reduced-motion:reduce){
    body::before,.worm i,.chip::before{animation:none}
    .value.pop{animation:none}
    .frame.eat{animation:none}
  }
</style>
