<body>
<main class="cab">

  <header class="masthead">
    <div class="logo">
      <span class="worm" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span>
      <h1>SNAKE</h1>
      <span class="tag">20×20 GRID</span>
    </div>
    <div class="statusbar">
      <span class="chip ready" id="mode" role="status">READY</span>
      <button id="snd" type="button" aria-pressed="true" title="Toggle sound">SND ●</button>
    </div>
  </header>

  <section class="hud" aria-label="Game statistics">
    <div class="stat primary"><span class="label">SCORE</span><span class="value" id="score">0</span></div>
    <div class="stat"><span class="label">BEST</span><span class="value" id="best">0</span></div>
    <div class="stat"><span class="label">LENGTH</span><span class="value" id="len">3</span></div>
    <div class="stat"><span class="label">SPEED</span><span class="value" id="spd">1.0×</span></div>
  </section>

  <div class="frame" id="frame">
    <canvas id="snake" width="480" height="480" aria-label="Snake game board"></canvas>
    <div class="scan" aria-hidden="true"></div>
    <div class="banner hidden" id="banner"></div>
  </div>

  <div class="controls">
    <button id="start" type="button">▶ START</button>
    <button id="pause" type="button">❚❚ PAUSE</button>
    <button id="reset" type="button">↺ RESET</button>
  </div>

  <footer class="keys">
    <span><kbd>↑</kbd><kbd>↓</kbd><kbd>←</kbd><kbd>→</kbd> steer</span>
    <span><kbd>SPACE</kbd> start / pause</span>
    <span><kbd>R</kbd> reset</span>
  </footer>

</main>

<script>
(() => {
'use strict';

/* ── constants & elements ─────────────────────────────────────── */
const W = 20, H = 20, CELL = 24, SIZE = W * CELL;   // 480 × 480 css px
const DIRS = { up:[0,-1], down:[0,1], left:[-1,0], right:[1,0] };
const OPP  = { up:'down', down:'up', left:'right', right:'left' };
const BASE_MS = 150, MIN_MS = 75;

const canvas  = document.getElementById('snake');
const ctx     = canvas.getContext('2d');
const frameEl = document.getElementById('frame');
const banner  = document.getElementById('banner');
const modeEl  = document.getElementById('mode');
const scoreEl = document.getElementById('score');
const bestEl  = document.getElementById('best');
const lenEl   = document.getElementById('len');
const spdEl   = document.getElementById('spd');
const startBtn= document.getElementById('start');
const pauseBtn= document.getElementById('pause');
const resetBtn= document.getElementById('reset');
const sndBtn  = document.getElementById('snd');

/* ── state ────────────────────────────────────────────────────── */
let snakeArr = [], dirName = 'right', pendingName = null;
let foodPos = null, scoreVal = 0, isAlive = true, won = false;
let mode = 'ready';                       // ready | running | paused | over
let particles = [], floaters = [];
let shake = 0, flash = 0;
let best = 0;
try { best = +localStorage.getItem('snake-best') || 0; } catch(e){}

const interval = () => Math.max(MIN_MS, BASE_MS - scoreVal * 4);

/* ── audio (tiny synth, no assets) ────────────────────────────── */
let actx = null, muted = false;
function beep(freq, dur, type, gain, slide){
  if (muted) return;
  try{
    actx = actx || new (window.AudioContext || window.webkitAudioContext)();
    if (actx.state === 'suspended') actx.resume();
    const t = actx.currentTime;
    const o = actx.createOscillator(), g = actx.createGain();
    o.type = type || 'square';
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(40, freq + slide), t + dur);
    g.gain.setValueAtTime(gain || .045, t);
    g.gain.exponentialRampToValueAtTime(.0001, t + dur);
    o.connect(g); g.connect(actx.destination);
    o.start(t); o.stop(t + dur + .02);
  }catch(e){}
}
const sfxEat   = () => { beep(560,.06,'square',.05); setTimeout(() => beep(840,.07,'square',.045), 55); };
const sfxDie   = () => beep(280,.4,'sawtooth',.06,-230);
const sfxStart = () => beep(440,.06,'triangle',.04);
const sfxPause = () => beep(330,.05,'triangle',.035);

/* ── canvas setup & pre-rendered board ────────────────────────── */
let dpr = 1;
const boardCv = document.createElement('canvas');
function fit(){
  dpr = Math.max(1, Math.min(2.5, window.devicePixelRatio || 1));
  canvas.width = SIZE * dpr; canvas.height = SIZE * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  buildBoard();
}
function buildBoard(){
  boardCv.width = SIZE * dpr; boardCv.height = SIZE * dpr;
  const b = boardCv.getContext('2d');
  b.setTransform(dpr, 0, 0, dpr, 0, 0);
  b.fillStyle = '#0a130f'; b.fillRect(0, 0, SIZE, SIZE);
  for (let y = 0; y < H; y++)
    for (let x = 0; x < W; x++)
      if ((x + y) & 1){ b.fillStyle = '#0d1811'; b.fillRect(x*CELL, y*CELL, CELL, CELL); }
  b.strokeStyle = 'rgba(140,220,180,.05)'; b.lineWidth = 1;
  b.beginPath();
  for (let i = 1; i < W; i++){ b.moveTo(i*CELL, 0); b.lineTo(i*CELL, SIZE); }
  for (let j = 1; j < H; j++){ b.moveTo(0, j*CELL); b.lineTo(SIZE, j*CELL); }
  b.stroke();
  const g = b.createRadialGradient(SIZE/2, SIZE/2, SIZE*.34, SIZE/2, SIZE/2, SIZE*.78);
  g.addColorStop(0, 'rgba(0,0,0,0)'); g.addColorStop(1, 'rgba(0,0,0,.38)');
  b.fillStyle = g; b.fillRect(0, 0, SIZE, SIZE);
}
window.addEventListener('resize', fit);

/* ── core rules ───────────────────────────────────────────────── */
function spawnFood(){
  const occ = new Set(snakeArr.map(p => p[0] + ',' + p[1]));
  const free = [];
  for (let y = 0; y < H; y++)
    for (let x = 0; x < W; x++)
      if (!occ.has(x + ',' + y)) free.push([x, y]);
  if (!free.length){ foodPos = null; winGame(); return; }
  foodPos = free[(Math.random() * free.length) | 0];
}

function tick(){
  if (!isAlive) return;
  if (pendingName){ dirName = pendingName; pendingName = null; }
  const d = DIRS[dirName], head = snakeArr[0];
  const nx = head[0] + d[0], ny = head[1] + d[1];

  if (nx < 0 || ny < 0 || nx >= W || ny >= H){ die(); return; }        // wall

  const willGrow = !!(foodPos && nx === foodPos[0] && ny === foodPos[1]);
  const body = willGrow ? snakeArr : snakeArr.slice(0, -1);             // tail vacates
  for (const s of body)
    if (s[0] === nx && s[1] === ny){ die(); return; }                   // self

  snakeArr.unshift([nx, ny]);
  if (willGrow){
    scoreVal++;
    onEat(nx, ny);
    spawnFood();
  } else {
    snakeArr.pop();
  }
  updateHUD();
}

function setDir(name){
  const d = DIRS[name];
  if (!d) return false;
  const cur = DIRS[dirName];
  if (d[0] === -cur[0] && d[1] === -cur[1]) return false;   // 180° reversal → ignored
  pendingName = name;
  return true;
}

function die(){
  if (!isAlive) return;
  isAlive = false; mode = 'over';
  shake = 15; flash = 1;
  const [hx, hy] = snakeArr[0];
  burst(hx * CELL + CELL/2, hy * CELL + CELL/2, ['#ff5d4d','#ffb454','#ff8a5c'], 20);
  if (scoreVal > best){
    best = scoreVal;
    try { localStorage.setItem('snake-best', best); } catch(e){}
  }
  sfxDie(); updateHUD(); ui();
}

function winGame(){
  mode = 'over'; won = true;
  if (scoreVal > best){ best = scoreVal; try{ localStorage.setItem('snake-best', best); }catch(e){} }
  updateHUD(); ui();
}

function resetState(){
  const cy = (H / 2) | 0, hx = ((W / 2) | 0) - 1;
  snakeArr = [[hx, cy], [hx-1, cy], [hx-2, cy]];   // head first, length 3
  dirName = 'right'; pendingName = null;
  scoreVal = 0; isAlive = true; won = false; mode = 'ready';
  particles.length = 0; floaters.length = 0;
  shake = 0; flash = 0;
  spawnFood();
  updateHUD(); ui();
}

/* ── effects ──────────────────────────────────────────────────── */
function burst(px, py, colors, n){
  for (let i = 0; i < n; i++){
    const a = Math.random() * Math.PI * 2, sp = .6 + Math.random() * 2.1;
    particles.push({ x:px, y:py, vx:Math.cos(a)*sp, vy:Math.sin(a)*sp,
      t:0, life:450 + Math.random()*380, r:1.6 + Math.random()*2.4,
      c:colors[(Math.random()*colors.length)|0] });
  }
}
function onEat(cx, cy){
  const px = cx * CELL + CELL/2, py = cy * CELL + CELL/2;
  burst(px, py, ['#b6f04a','#ffd166','#ff5d4d','#39d2a8'], 14);
  floaters.push({ x:px, y:py - 6, t:0, life:760 });
  frameEl.classList.remove('eat'); void frameEl.offsetWidth; frameEl.classList.add('eat');
  sfxEat();
}
function updateFx(dt){
  shake *= Math.exp(-dt / 110); if (shake < .3) shake = 0;
  flash *= Math.exp(-dt / 260);
  for (let i = particles.length - 1; i >= 0; i--){
    const p = particles[i];
    p.t += dt; if (p.t > p.life){ particles.splice(i, 1); continue; }
    p.x += p.vx * dt / 16; p.y += p.vy * dt / 16;
    p.vx *= .985; p.vy *= .985;
  }
  for (let i = floaters.length - 1; i >= 0; i--){
    const f = floaters[i]; f.t += dt; f.y -= dt * .032;
    if (f.t > f.life) floaters.splice(i, 1);
  }
}

/* ── rendering ────────────────────────────────────────────────── */
const px = c => c * CELL + CELL / 2;
function segColor(t){
  if (!isAlive) return `hsl(${100 + t*40} 12% ${36 - t*12}%)`;
  return `hsl(${86 + t*72} ${92 - t*28}% ${60 - t*28}%)`;
}
function drawFood(now){
  if (!foodPos) return;
  const fx = px(foodPos[0]), fy = px(foodPos[1]);
  const pulse = Math.sin(now / 270);
  const r = CELL * .30 + pulse * 1.6;
  const phase = (now % 1100) / 1100;
  ctx.strokeStyle = `rgba(255,93,77,${(1 - phase) * .22})`;
  ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.arc(fx, fy, CELL*.34 + phase * CELL*.55, 0, 7); ctx.stroke();
  ctx.save();
  ctx.shadowColor = 'rgba(255,93,77,.8)'; ctx.shadowBlur = 14 + pulse * 3;
  const g = ctx.createRadialGradient(fx - r*.35, fy - r*.4, r*.15, fx, fy, r);
  g.addColorStop(0, '#ffd0a8'); g.addColorStop(.35, '#ff7a5c'); g.addColorStop(1, '#e03a3a');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(fx, fy, r, 0, 7); ctx.fill();
  ctx.restore();
  ctx.save();                                             // leaf
  ctx.translate(fx + 2, fy - r - 2); ctx.rotate(-.6);
  ctx.fillStyle = '#67d97a';
  ctx.beginPath(); ctx.ellipse(0, 0, 4.4, 2.1, 0, 0, 7); ctx.fill();
  ctx.restore();
  ctx.fillStyle = 'rgba(255,255,255,.85)';
  ctx.beginPath(); ctx.arc(fx - r*.32, fy - r*.38, r*.18, 0, 7); ctx.fill();
}
function drawSnake(now){
  const len = snakeArr.length;
  ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  for (let i = len - 1; i > 0; i--){
    ctx.strokeStyle = segColor(i / Math.max(1, len - 1));
    ctx.lineWidth = CELL * .66;
    ctx.beginPath();
    ctx.moveTo(px(snakeArr[i][0]), px(snakeArr[i][1]));
    ctx.lineTo(px(snakeArr[i-1][0]), px(snakeArr[i-1][1]));
    ctx.stroke();
  }
  const hx = px(snakeArr[0][0]), hy = px(snakeArr[0][1]);
  const d = DIRS[dirName], perp = [-d[1], d[0]];
  ctx.save();
  if (isAlive){ ctx.shadowColor = 'rgba(182,240,74,.55)'; ctx.shadowBlur = 13; }
  ctx.fillStyle = segColor(0);
  ctx.beginPath(); ctx.arc(hx, hy, CELL * .5, 0, 7); ctx.fill();
  ctx.restore();
  ctx.strokeStyle = 'rgba(0,0,0,.35)'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(hx, hy, CELL * .5, 0, 7); ctx.stroke();

  const fwd = CELL * .14, side = CELL * .18, er = CELL * .115;
  const blink = isAlive && (now % 3400) < 110;
  for (const sgn of [-1, 1]){
    const ex = hx + d[0]*fwd + perp[0]*side*sgn;
    const ey = hy + d[1]*fwd + perp[1]*side*sgn;
    if (!isAlive){                                          // X eyes
      ctx.strokeStyle = '#0a130f'; ctx.lineWidth = 1.8;
      ctx.beginPath();
      ctx.moveTo(ex-2.6, ey-2.6); ctx.lineTo(ex+2.6, ey+2.6);
      ctx.moveTo(ex+2.6, ey-2.6); ctx.lineTo(ex-2.6, ey+2.6);
      ctx.stroke();
    } else if (blink){
      ctx.strokeStyle = '#0a130f'; ctx.lineWidth = 1.8;
      ctx.beginPath(); ctx.moveTo(ex-2.6, ey); ctx.lineTo(ex+2.6, ey); ctx.stroke();
    } else {
      ctx.fillStyle = '#f4fff0';
      ctx.beginPath(); ctx.arc(ex, ey, er, 0, 7); ctx.fill();
      ctx.fillStyle = '#10231a';
      ctx.beginPath(); ctx.arc(ex + d[0]*1.5, ey + d[1]*1.5, er*.52, 0, 7); ctx.fill();
