}
function drawFx(){
  for (const p of particles){
    ctx.globalAlpha = Math.max(0, 1 - p.t / p.life);
    ctx.fillStyle = p.c;
    ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, 7); ctx.fill();
  }
  ctx.globalAlpha = 1;
  ctx.font = '700 15px ui-monospace, Menlo, Consolas, monospace';
  ctx.textAlign = 'center';
  for (const f of floaters){
    ctx.globalAlpha = Math.max(0, 1 - f.t / f.life);
    ctx.fillStyle = '#b6f04a';
    ctx.shadowColor = 'rgba(182,240,74,.7)'; ctx.shadowBlur = 8;
    ctx.fillText('+1', f.x, f.y);
    ctx.shadowBlur = 0;
  }
  ctx.globalAlpha = 1;
}
function render(now){
  ctx.save();
  ctx.fillStyle = '#0a130f';
  ctx.fillRect(-30, -30, SIZE + 60, SIZE + 60);
  if (shake > 0) ctx.translate((Math.random()-.5)*shake, (Math.random()-.5)*shake);
  ctx.drawImage(boardCv, 0, 0, SIZE, SIZE);
  drawFood(now);
  drawSnake(now);
  drawFx();
  ctx.restore();
  if (flash > .01){
    ctx.fillStyle = `rgba(255,64,52,${flash * .24})`;
