}

/* ── HUD / UI chrome ──────────────────────────────────────────── */
let shownScore = -1;
function updateHUD(){
  if (scoreVal !== shownScore){
    scoreEl.textContent = scoreVal;
    if (shownScore >= 0){
      scoreEl.classList.remove('pop'); void scoreEl.offsetWidth; scoreEl.classList.add('pop');
    }
    shownScore = scoreVal;
  }
  bestEl.textContent = best;
  lenEl.textContent = snakeArr.length;
  spdEl.textContent = (BASE_MS / interval()).toFixed(1) + '×';
}
function ui(){
  const st = !isAlive ? (won ? 'win' : 'over') : mode;
  modeEl.textContent = !isAlive ? (won ? 'CLEARED' : 'GAME OVER')
    : { ready:'READY', running:'RUNNING', paused:'PAUSED' }[mode];
  modeEl.className = 'chip ' + st;

  pauseBtn.disabled = !isAlive;
  pauseBtn.innerHTML = (mode === 'paused') ? '► RESUME' : '❚❚ PAUSE';
  startBtn.classList.toggle('dim', isAlive && mode === 'running');

  let txt = null, cls = '';
  if (!isAlive){
    if (won){ txt = '★ BOARD CLEARED — PERFECT RUN ★'; cls = 'win'; }
    else { txt = `GAME OVER · SCORE ${scoreVal} · PRESS R TO RETRY`; cls = 'over'; }
  } else if (mode === 'ready'){
    txt = 'PRESS ▶ START — OR ANY ARROW KEY — TO BEGIN'; cls = 'ready';
  } else if (mode === 'paused'){
    txt = 'PAUSED · SPACE TO RESUME'; cls = 'paused';
  }
  banner.textContent = txt || '';
  banner.className = 'banner' + (txt ? ' ' + cls : ' hidden');
}

/* ── flow control ─────────────────────────────────────────────── */
function run(){
  if (!isAlive) resetState();
  if (mode !== 'running'){ mode = 'running'; sfxStart(); ui(); }
}
function togglePause(){
  if (!isAlive) return;
  if (mode === 'running'){ mode = 'paused'; sfxPause(); }
  else if (mode === 'paused' || mode === 'ready'){ mode = 'running'; sfxStart(); }
  ui();
}
startBtn.addEventListener('click', function(){ run(); this.blur(); });
pauseBtn.addEventListener('click', function(){ togglePause(); this.blur(); });
resetBtn.addEventListener('click', function(){ resetState(); sfxPause(); this.blur(); });
sndBtn.addEventListener('click', function(){
  muted = !muted;
  this.textContent = muted ? 'SND ○' : 'SND ●';
  this.setAttribute('aria-pressed', String(!muted));
  this.blur();
});

/* ── keyboard ─────────────────────────────────────────────────── */
const KEYMAP = {
  ArrowUp:'up', ArrowDown:'down', ArrowLeft:'left', ArrowRight:'right',
  w:'up', s:'down', a:'left', d:'right'
};
window.addEventListener('keydown', e => {
  const k = e.key, dir = KEYMAP[k] || KEYMAP[(k || '').toLowerCase()];
  if (dir){
    e.preventDefault();
    game.setDir(dir);
    if (isAlive && mode === 'ready') run();       // first arrow launches
    return;
  }
  if (k === ' '){
    e.preventDefault();
    if (!isAlive){ resetState(); run(); }
    else togglePause();
    return;
  }
  if (k === 'Enter'){ e.preventDefault(); run(); return; }
  if (k === 'r' || k === 'R'){ resetState(); }
