document.addEventListener('visibilitychange', () => {
  if (document.hidden && mode === 'running'){ mode = 'paused'; ui(); }
});

/* ── main loop ────────────────────────────────────────────────── */
let last = performance.now(), acc = 0;
function frame(now){
  requestAnimationFrame(frame);
  const dt = Math.min(50, now - last); last = now;
  if (mode === 'running' && isAlive){
    acc += dt;
    let guard = 0;
    while (acc >= interval() && guard++ < 6){
      acc -= interval();
      tick();
      if (!isAlive) break;
    }
  } else acc = 0;
  updateFx(dt);
  render(now);
}

/* ── programmatic API (grading contract) ──────────────────────── */
window.game = {
