  h: H,
  reset(){ resetState(); },
  tick(){ tick(); },
  setDir(name){ return setDir(name); },
  setFood(x, y){ foodPos = [x | 0, y | 0]; },   // render loop redraws immediately
  snake(){ return snakeArr.map(p => [p[0], p[1]]); },  // head first
  food(){ return foodPos ? [foodPos[0], foodPos[1]] : null; },
  alive(){ return isAlive; },
  score(){ return scoreVal; },
};

/* ── boot ─────────────────────────────────────────────────────── */
fit();
resetState();
requestAnimationFrame(frame);

})();
